with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('boks', 'word', '6bdd0b66-3efc-5a91-bc5f-57b823fa7383', 1, 'noun', 'en', 'box', 'Hun pakkede tingene ned i en boks.', 'She packed the things into a box.'), ('afklare', 'word', '48c05a67-1df6-5895-a779-df51f6077294', 1, 'verb', null, 'to clarify, sort out', 'Vi må afklare situationen først.', 'We must clarify the situation first.'), ('lettelse', 'word', 'd7da7dfe-fbe7-5c65-9698-d0dc3bfee532', 1, 'noun', 'en', 'relief', 'Hun følte en stor lettelse efter beskeden.', 'She felt great relief after the news.'), ('opbevare', 'word', '05176498-0e4f-5326-91f8-383150ed3df0', 1, 'verb', null, 'to store, keep', 'Vi opbevarer maden i køleskabet.', 'We store the food in the fridge.'), ('popularitet', 'word', '395e8d81-b6b1-5c51-9203-722c0c6f3e17', 1, 'noun', 'en', 'popularity', 'Sangens popularitet steg hurtigt.', 'The song''s popularity rose quickly.'), ('indsat', 'word', '05ed68ec-e795-5d10-a85c-00b6fee4d2c6', 1, 'adjective', null, 'imprisoned, in custody', 'Han er indsat i et fængsel.', 'He is imprisoned in a jail.'), ('spanier', 'word', '707d6723-fda8-5519-9906-72c3e22bcca8', 1, 'noun', 'en', 'Spaniard', 'Han er spanier og bor i Madrid.', 'He is Spanish and lives in Madrid.'), ('får', 'word', 'eb971476-53d7-563b-b6db-f8a91faa089b', 1, 'noun', 'et', 'sheep', 'Fårene græssede på marken.', 'The sheep were grazing in the field.'), ('tredjeplads', 'word', '96efddc3-ee05-5858-9073-c2e043d5562b', 1, 'noun', 'en', 'third place', 'Hun fik en tredjeplads i løbet.', 'She got third place in the race.'), ('suppe', 'word', '9960bfef-537f-5c02-8ca8-fb4da61b491d', 1, 'noun', 'en', 'soup', 'Hun lavede suppe til frokost.', 'She made soup for lunch.'), ('bonus', 'word', '249383a7-99f0-58da-bf57-6225eff5905e', 1, 'noun', 'en', 'bonus', 'Han fik en bonus for godt arbejde.', 'He got a bonus for good work.'), ('komiker', 'word', 'dac25940-7315-5c88-940d-e048f697ae17', 1, 'noun', 'en', 'comedian