med a coalition.'), ('tandlæge', 'word', '88eaea94-f5c4-5df3-b14f-48a5ea9a3300', 1, 'noun', 'en', 'dentist', 'Jeg skal til tandlæge i morgen.', 'I have a dentist appointment tomorrow.'), ('rytmisk', 'word', '08525499-3949-5a6d-bffe-76de9428185f', 1, 'adjective', null, 'rhythmic', 'Musikken havde en rytmisk lyd.', 'The music had a rhythmic sound.'), ('fuldkommen', 'word', '9d5ed210-c1c0-5f72-ab1a-0ef8b73c4696', 1, 'adjective', null, 'complete, absolute', 'Det var et fuldkomment kaos.', 'It was absolute chaos.'), ('overtagelse', 'word', 'b2887be3-2634-5f55-b31c-d4765618b34f', 1, 'noun', 'en', 'takeover', 'Firmaet blev ramt af en fjendtlig overtagelse.', 'The company was hit by a hostile takeover.'), ('gerning', 'word', '06de0ba3-1edc-5c00-bc2f-677194759139', 1, 'noun', 'en', 'deed, act', 'Det var en modig gerning.', 'It was a brave deed.'), ('vedligeholdelse', 'word', 'ccab9563-c492-545d-a983-0b64423f8ced', 1, 'noun', 'en', 'maintenance, upkeep', 'Huset kræver løbende vedligeholdelse.', 'The house requires ongoing maintenance.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'locale-en-2026-09-25' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
